#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-09

# Test: agent-messaging lifecycle scope (#3316)
#
# Peer messaging is a capability, not a decoration. Two rules, asserted over
# EVERY src/agents/*.md rather than a hardcoded roster, so agent #37 is covered
# the day it lands:
#
#   (a) An agent that is `background: true` must NOT carry `SendMessage` in
#       its tools list — no exemptions, including Agent-Teams teammates.
#       agent-teams.md (verified 2026-08-09): "Team coordination tools such
#       as `SendMessage` ... are always available to a teammate even when
#       `tools` restricts other tools." So a teammate NEVER needs the
#       frontmatter grant — CC force-grants it inside a team — and outside a
#       team the grant is exactly the unattended ambient capability #3316
#       exists to remove. A tools: grant on a background agent is therefore
#       either redundant (team run) or a hole (background run); both wrong.
#
#   (b) An agent that carries `SendMessage` and is NOT `background: true`
#       MUST also carry `ListAgents`. A foreground sender must be able to
#       enumerate live peers so it addresses rather than guesses.
#
#
# Frontmatter matches are counted INSIDE the first ---...--- fence only, so a
# prose mention of SendMessage never false-positives the tools check. The
# "Agent Teams" probe deliberately reads the BODY (after the fence).
#
# Overridable for differential testing:
#   AGENTS_DIR=<dir> bash tests/agents/test-agent-messaging-scope.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

AGENTS_DIR="${AGENTS_DIR:-$REPO_ROOT/src/agents}"

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[0;33m'
NC='\033[0m'

PASS_COUNT=0
FAIL_COUNT=0

log_pass() {
  PASS_COUNT=$((PASS_COUNT + 1))
  printf "${GREEN}PASS${NC}: %s\n" "$1"
}

log_fail() {
  FAIL_COUNT=$((FAIL_COUNT + 1))
  printf "${RED}FAIL${NC}: %s\n" "$1"
}

# Count lines matching a frontmatter tools entry, first ---...--- fence only.
fm_tool_count() {
  awk -v tool="$2" '
    /^---$/ { fence++; next }
    fence == 1 && $0 == "  - " tool { n++ }
    END { print n+0 }
  ' "$1"
}

# Count `background: true` declarations inside the frontmatter fence.
fm_background_count() {
  awk '
    /^---$/ { fence++; next }
    fence == 1 && /^background:[[:space:]]*true[[:space:]]*$/ { n++ }
    END { print n+0 }
  ' "$1"
}

echo "=== Agent messaging scope test (#3316) ==="
echo "Agents dir:    $AGENTS_DIR"
echo ""

if [ ! -d "$AGENTS_DIR" ]; then
  echo -e "${RED}ERROR: agents dir not found: $AGENTS_DIR${NC}"
  exit 1
fi

AGENTS_CHECKED=0

for agent_file in "$AGENTS_DIR"/*.md; do
  agent_name=$(basename "$agent_file" .md)

  case "$agent_name" in
    README|INDEX|CONTRIBUTING) continue ;;
  esac

  AGENTS_CHECKED=$((AGENTS_CHECKED + 1))

  has_send=$(fm_tool_count "$agent_file" "SendMessage")
  has_list=$(fm_tool_count "$agent_file" "ListAgents")
  is_background=$(fm_background_count "$agent_file")

  agent_failed=0

  # (a) background agents never need the frontmatter grant: CC force-grants
  # SendMessage to teammates inside a team, so the tools: entry is live ONLY
  # in unattended background runs — the context #3316 exists to close.
  if [ "$is_background" -gt 0 ] && [ "$has_send" -gt 0 ]; then
    log_fail "$agent_name declares SendMessage while background:true — teammates get it force-granted inside a team (agent-teams.md), so this grant is live only in unattended runs (#3316)"
    agent_failed=1
  fi

  # (b) foreground sender must be able to enumerate peers
  if [ "$has_send" -gt 0 ] && [ "$is_background" -eq 0 ] && [ "$has_list" -eq 0 ]; then
    log_fail "$agent_name declares SendMessage without ListAgents — a foreground sender must be able to enumerate live peers so it addresses rather than guesses (#3316)"
    agent_failed=1
  fi

  if [ "$agent_failed" -eq 0 ]; then
    log_pass "$agent_name messaging scope is coherent"
  fi
done

echo ""
echo "========================================"
echo "  Summary"
echo "========================================"
echo "Agents checked: $AGENTS_CHECKED"
echo -e "Passed: ${GREEN}$PASS_COUNT${NC}"
echo -e "Failed: ${RED}$FAIL_COUNT${NC}"

if [ "$FAIL_COUNT" -gt 0 ]; then
  echo ""
  echo -e "${YELLOW}Fix: revoke SendMessage from every background:true agent (teams force-grant it);${NC}"
  echo -e "${YELLOW}grant ListAgents alongside SendMessage on foreground agents.${NC}"
  echo -e "${RED}Agent messaging scope test FAILED${NC}"
  exit 1
fi

echo ""
echo -e "${GREEN}Agent messaging scope test PASSED${NC}"
exit 0
